const SQ1 = T(75); // se apaga en "deja"

// ---------- utilidades
const ease = (a: number) => a * a * (3 - 2 * a);
const ramp = (s: number, a: number, b: number) => ease(Math.max(0, Math.min(1, (s - a) / Math.max(1e-6, b - a))));
const mix = (a: number, b: number, q: number) => a + (b - a) * q;
const mx = (a: number[], b: number[], q: number): number[] => [mix(a[0], b[0], q), mix(a[1], b[1], q)];

