// ---------- degradados y trazos compartidos
const G = (id: string, a: string, b: string, c: string, x1 = 0, y1 = 0, x2 = 1, y2 = 1) => (
  <linearGradient id={id} x1={x1} y1={y1} x2={x2} y2={y2}>
