// ---------- el pie visto desde arriba (dedos hacia abajo, pierna hacia arriba)
const TOES = [
  {x: -80, y: -110, rx: 38, ry: 54},
  {x: -28, y: -112, rx: 27, ry: 40},
  {x: 20, y: -100, rx: 25, ry: 36},
  {x: 60, y: -84, rx: 22, ry: 31},
  {x: 94, y: -62, rx: 19, ry: 26},
];
const CUERPO = 'M -120 -62 C -118 30 -101 90 -107 170 C -111 235 -90 300 -72 340 C -30 354 20 356 60 345 C 91 330 93 260 102 180 C 114 100 127 20 118 -58 C 40 -80 -90 -80 -120 -62 Z';
const CUERPO_P = 'M -120 -62 C -118 30 -101 90 -107 170 C -111 235 -76 285 -66 320 L -88 1700 L 88 1700 L 66 320 C 84 285 96 235 102 180 C 114 100 127 20 118 -58 C 40 -80 -90 -80 -120 -62 Z';

const Formas: React.FC<{rot: number[]; pierna: boolean; fill?: string; stroke?: string; sw?: number}> = ({rot, pierna, fill, stroke, sw}) => (
  <>
    <path d={pierna ? CUERPO_P : CUERPO} fill={fill} stroke={stroke} strokeWidth={sw} strokeLinejoin="round" />
    {TOES.map((t, i) => (
      <ellipse key={i} cx={t.x} cy={t.y} rx={t.rx} ry={t.ry} fill={fill} stroke={stroke} strokeWidth={sw} transform={`rotate(${rot[i]} ${t.x} ${t.y + t.ry * 0.75})`} />
    ))}
  </>
);

const Pie: React.FC<{uid: string; rot: number[]; tono?: 'piel' | 'palido' | 'gris'; madera?: number; wipe?: number; pierna?: boolean; sombra?: boolean}> = ({uid, rot, tono: tn = 'piel', madera = 0, wipe = 1, pierna = true, sombra = true}) => {
  const g = tn === 'piel' ? 'skF' : tn === 'palido' ? 'skpF' : 'skgF';
  const borde = tn === 'gris' ? '#3d485c' : '#6e4328';
  const poro = tn === 'gris' ? '#26303f' : '#5a3520';
  const ymax = pierna ? 900 : 330;
  return (
    <g transform="scale(1 -1)">
      <defs>
        <clipPath id={uid}>
          <Formas rot={rot} pierna={pierna} />
        </clipPath>
        <clipPath id={uid + 'w'}>
          <rect x={-400} y={-400} width={800} height={Math.max(1, wipe * 2300)} />
        </clipPath>
      </defs>
      {sombra && (
        <>
          <g transform="translate(26 -32)" opacity={0.2}><Formas rot={rot} pierna={pierna} fill="#000" /></g>
          <g transform="translate(12 -15)" opacity={0.18}><Formas rot={rot} pierna={pierna} fill="#000" /></g>
        </>
      )}
      <Formas rot={rot} pierna={pierna} fill={`url(#${g})`} stroke={borde} sw={3} />
      <g clipPath={`url(#${uid})`}>
        <g opacity={0.24}><Formas rot={rot} pierna={pierna} fill="none" stroke="#2f1708" sw={18} /></g>
        <ellipse cx={-34} cy={-10} rx={62} ry={92} fill="#fff" opacity={0.1} />
        <ellipse cx={-78} cy={-8} rx={26} ry={70} fill="#fff" opacity={0.08} />
        <path d="M -108 120 C -80 150 -66 230 -70 318 L -112 300 Z" fill="#2f1708" opacity={0.13} />
        {[-60, -18, 24, 64].map((x, i) => (
          <g key={'t' + i}>
            <path d={`M ${x} 300 C ${x + 6} 160 ${x - 10} 40 ${x + (i - 1.5) * 12} -60`} stroke="#fff" strokeWidth={10} fill="none" opacity={0.1} />
            <path d={`M ${x + 8} 300 C ${x + 14} 160 ${x - 2} 40 ${x + (i - 1.5) * 12 + 8} -60`} stroke="#2f1708" strokeWidth={2.5} fill="none" opacity={0.14} />
          </g>
        ))}
        {TOES.map((t, i) => (
          <g key={'d' + i}>
            <ellipse cx={t.x - t.rx * 0.3} cy={t.y - t.ry * 0.35 + 0} rx={t.rx * 0.34} ry={t.ry * 0.3} fill="#fff" opacity={0.2} transform={`rotate(${rot[i]} ${t.x} ${t.y + t.ry * 0.75})`} />
            <path d={`M ${t.x - t.rx * 0.6} ${t.y + t.ry * 0.5} Q ${t.x} ${t.y + t.ry * 0.62} ${t.x + t.rx * 0.6} ${t.y + t.ry * 0.5}`} stroke="#2f1708" strokeWidth={2.5} fill="none" opacity={0.2} />
          </g>
        ))}
        {Array.from({length: 120}, (_, i) => (
          <circle key={'p' + i} cx={-105 + h(i * 3 + 1) * 210} cy={-70 + h(i * 5 + 2) * (ymax + 70)} r={1.2 + h(i * 7) * 1.8} fill={poro} opacity={0.34} />
        ))}
        {Array.from({length: 46}, (_, i) => {
          const x = -100 + h(i * 11 + 5) * 200;
          const y = -50 + h(i * 13 + 9) * (ymax + 40);
          const dx = (h(i * 17) - 0.5) * 9;
          return <path key={'v' + i} d={`M ${x} ${y} q ${dx * 0.3} -7 ${dx} -15`} stroke={tn === 'gris' ? '#1f2735' : '#3b2214'} strokeWidth={1.7} fill="none" opacity={0.5} />;
        })}
        {[-80, -28, 20].map((x, i) => (
          <path key={'hv' + i} d={`M ${x - 6} ${-100 - i * 6} q 3 -8 5 -16 M ${x + 6} ${-96 - i * 6} q 2 -7 4 -14`} stroke="#3b2214" strokeWidth={1.6} fill="none" opacity={0.4} />
        ))}
      </g>
      {TOES.map((t, i) => (
        <g key={'n' + i} transform={`rotate(${rot[i]} ${t.x} ${t.y + t.ry * 0.75})`}>
          <ellipse cx={t.x} cy={t.y - t.ry * 0.58} rx={t.rx * 0.6} ry={t.ry * 0.3} fill={tn === 'gris' ? '#c8d0dc' : '#f6d9cb'} stroke={tn === 'gris' ? '#6d7b92' : '#b88a72'} strokeWidth={2} opacity={0.92} />
          <ellipse cx={t.x - t.rx * 0.18} cy={t.y - t.ry * 0.66} rx={t.rx * 0.2} ry={t.ry * 0.08} fill="#fff" opacity={0.7} />
        </g>
      ))}
      {madera > 0.001 && (
        <g clipPath={`url(#${uid})`} opacity={madera}>
          <g clipPath={`url(#${uid}w)`}>
            <rect x={-300} y={-300} width={600} height={2300} fill="url(#wdF)" />
            {Array.from({length: 18}, (_, i) => {
              const x0 = -140 + i * 16 + h(i) * 6;
              return <path key={'w' + i} d={`M ${x0} -200 C ${x0 + 16 * (h(i * 3) - 0.3)} 100 ${x0 - 14} 420 ${x0 + 6} 1000`} stroke="#3e2512" strokeWidth={2 + h(i * 5) * 3.5} fill="none" opacity={0.45} />;
            })}
            {[[30, 30, 38], [-55, 210, 30], [24, 640, 40]].map(([cx, cy, r], i) => (
              <g key={'k' + i}>
                {[1, 0.7, 0.42].map((m, j) => <ellipse key={j} cx={cx} cy={cy} rx={r * m} ry={r * m * 1.5} fill="none" stroke="#3a2210" strokeWidth={3} opacity={0.5} />)}
              </g>
            ))}
            <ellipse cx={-40} cy={0} rx={70} ry={110} fill="#ffe3b3" opacity={0.12} />
          </g>
        </g>
      )}
    </g>
  );
};

// ---------- suelo de madera
const Piso: React.FC = () => {
  const tones = ['#a97c4f', '#9b6f45', '#b68859', '#92683f', '#a67649'];
  const planks: React.ReactNode[] = [];
  for (let r = -1; r < 15; r++) {
    const y = r * 150;
    const off = (r % 3) * 170;
    for (let k = -1; k < 4; k++) {
      const x = off + k * 520 - 260;
      const hi = h(r * 13 + k * 3 + 1);
      const d = h(r * 7 + k) * 24;
      planks.push(
        <g key={r + '_' + k}>
          <rect x={x} y={y} width={520} height={150} fill={tones[Math.floor(hi * 5)]} stroke="#2f1b0d" strokeWidth={5} />
          {[0, 1, 2].map((g) => (
            <path key={g} d={`M ${x + 14} ${y + 28 + g * 46} C ${x + 160} ${y + 18 + g * 46 + d} ${x + 330} ${y + 40 + g * 46 - d} ${x + 506} ${y + 30 + g * 46}`} stroke="#5a381c" strokeWidth={2.5} fill="none" opacity={0.35} />
          ))}
          <path d={`M ${x + 4} ${y + 4} H ${x + 516}`} stroke="#ffe6be" strokeWidth={3} opacity={0.22} />
          {hi > 0.7 && <ellipse cx={x + 120 + hi * 200} cy={y + 80} rx={16} ry={10} fill="none" stroke="#4a2c14" strokeWidth={3} opacity={0.5} />}
        </g>,
      );
    }
  }
  return <g>{planks}</g>;
};

// ---------- sitio 1: el pie en macro sobre el piso de madera
const rotDedos = (s: number) =>
  TOES.map((_, i) => {
    if (s < 20) {
      const p = (s * 1.15 + i * 0.13) % 1;
      return p < 0.28 ? Math.sin((p / 0.28) * Math.PI) * (4.2 - i * 0.4) : 0;
    }
    if (s < E[11]) {
      const a = interpolate(s, [tCosq - 0.2, tCosq + 0.3, E[11], E[11] + 0.3], [0, 1, 1, 0], clamp);
      return Math.sin(s * 19 + i * 2.1) * 2.8 * a;
    }
    const a = ramp(s, tOrden - 0.4, tTuyo + 0.2);
    return Math.sin(s * 7.5 + i * 0.95) * (1.5 + 13 * a);
  });

const PO = (x: number, y: number): [number, number] => [540 + 1.7 * x, 1180 - 1.7 * y];

const Aguja: React.FC<{x: number; y: number; t0: number; ang: number}> = ({x, y, t0, ang}) => {
  const {s} = useS();
  const d = s - t0;
  if (d < -0.02 || d > 0.6) return null;
  const [px, py] = PO(x, y);
  const p = d < 0.15 ? ramp(s, t0, t0 + 0.15) : d < 0.3 ? 1 : 1 - ramp(s, t0 + 0.3, t0 + 0.5);
  const dx = Math.sin((ang * Math.PI) / 180);
  const dy = -Math.cos((ang * Math.PI) / 180);
  const off = (1 - p) * 70;
  const tx = px + dx * off;
  const ty = py + dy * off;
  const ring = Math.max(0, (d - 0.12) / 0.4);
  return (
    <g>
      <line x1={tx + dx * 120} y1={ty + dy * 120} x2={tx} y2={ty} stroke="#fff" strokeWidth={5} strokeLinecap="round" />
      <line x1={tx + dx * 120} y1={ty + dy * 120} x2={tx} y2={ty} stroke={LIME} strokeWidth={9} strokeLinecap="round" opacity={0.55} />
      <circle cx={tx} cy={ty} r={14} fill={LIME} />
      {ring > 0 && ring < 1 && <circle cx={px} cy={py} r={14 + ring * 52} fill="none" stroke={LIME} strokeWidth={5} opacity={1 - ring} />}
    </g>
  );
};

const Reinicio: React.FC<{x: number; y: number; t0: number}> = ({x, y, t0}) => {
  const {s, spr} = useS();
  const a = spr(t0, 11, 190);
  if (a <= 0.001) return null;
  const ang = (s - t0) * 420;
  const arco = (a0: number, a1: number, r: number) => {
    const p = (a: number): [number, number] => [Math.cos((a * Math.PI) / 180) * r, Math.sin((a * Math.PI) / 180) * r];
    const [x0, y0] = p(a0);
    const [x1, y1] = p(a1);
    const tx = -Math.sin((a1 * Math.PI) / 180);
    const ty = Math.cos((a1 * Math.PI) / 180);
    const nx = Math.cos((a1 * Math.PI) / 180);
