const Limb: React.FC<{a: number[]; b: number[]; w0: number; w1: number; fill: string; luz?: boolean}> = ({a, b, w0, w1, fill, luz = true}) => {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const L = Math.hypot(dx, dy) || 1;
  let nx = -dy / L;
  let ny = dx / L;
  if (-nx - ny < 0) {
    nx = -nx;
    ny = -ny;
  }
  const q = (p: number[], n: number, w: number) => `${p[0] + nx * n * w} ${p[1] + ny * n * w}`;
  const d = `M ${q(a, 0.5, w0)} L ${q(b, 0.5, w1)} L ${q(b, -0.5, w1)} L ${q(a, -0.5, w0)} Z`;
  return (
    <g>
      <path d={d} fill={fill} stroke="rgba(30,12,4,0.45)" strokeWidth={3} strokeLinejoin="round" />
      <circle cx={a[0]} cy={a[1]} r={w0 / 2} fill={fill} />
      <circle cx={b[0]} cy={b[1]} r={w1 / 2} fill={fill} />
      {luz && <path d={`M ${q(a, 0.24, w0)} L ${q(b, 0.24, w1)}`} stroke="#fff" strokeWidth={Math.max(4, w1 * 0.2)} opacity={0.2} strokeLinecap="round" />}
      {luz && <path d={`M ${q(a, -0.3, w0)} L ${q(b, -0.3, w1)}`} stroke="#000" strokeWidth={Math.max(4, w1 * 0.24)} opacity={0.14} strokeLinecap="round" />}
    </g>
  );
};

