};

// ---------- sitio 3: el interior de la pierna (lámina médica)
const NY0 = -120;
const NY1 = 1750;
const YS = 880;
const nx = (y: number) => 440 + 34 * Math.sin(y / 330);
const NPTS: [number, number][] = Array.from({length: 38}, (_, i) => {
  const y = NY1 - ((NY1 - NY0) * i) / 37;
  return [nx(y), y] as [number, number];
});
const NPTS2: [number, number][] = [1500, 1300, 1100, YS].map((y) => [nx(y), y] as [number, number]);

const gau = (d: number, sg: number) => Math.exp(-(d * d) / (2 * sg * sg));
const ancho = (y: number, sq: number, sw: number) => 24 * (1 - 0.78 * sq * gau(y - YS, 48) + 0.3 * sq * (gau(y - YS - 120, 38) + gau(y - YS + 120, 38))) * (1 + sw);

const Musculo: React.FC<{x: number; y0: number; y1: number; w: number; sesgo?: number; fib?: number}> = ({x, y0, y1, w, sesgo = 0, fib = 8}) => {
  const N = 24;
  const cen = (i: number) => x + sesgo * Math.sin((i / N) * Math.PI);
  const hw = (i: number) => (w / 2) * (0.45 + 0.55 * Math.pow(Math.sin((i / N) * Math.PI), 0.8));
  const yy = (i: number) => y0 + ((y1 - y0) * i) / N;
  const L = Array.from({length: N + 1}, (_, i) => `${(cen(i) - hw(i)).toFixed(1)} ${yy(i).toFixed(1)}`);
  const R = Array.from({length: N + 1}, (_, i) => `${(cen(i) + hw(i)).toFixed(1)} ${yy(i).toFixed(1)}`).reverse();
  return (
    <g>
      <polygon points={L.concat(R).join(' ')} fill="url(#mu)" stroke="#3a0a14" strokeWidth={4} strokeLinejoin="round" />
      {Array.from({length: fib}, (_, f) => {
        const fr = (f + 1) / (fib + 1);
        return <polyline key={f} points={Array.from({length: N + 1}, (_, i) => `${(cen(i) + (fr - 0.5) * 2 * hw(i)).toFixed(1)} ${yy(i).toFixed(1)}`).join(' ')} fill="none" stroke={f % 2 ? '#ffb3a6' : '#3f0e18'} strokeWidth={f % 2 ? 2.5 : 3} opacity={f % 2 ? 0.2 : 0.3} />;
      })}
      <path d={`M ${cen(3) - hw(3) * 0.6} ${yy(3)} Q ${cen(12) - hw(12) * 0.5} ${yy(12)} ${cen(21) - hw(21) * 0.6} ${yy(21)}`} stroke="#fff" strokeWidth={9} fill="none" opacity={0.1} strokeLinecap="round" />
    </g>
  );
};

const Nervio: React.FC<{p: number; sq: number; sw: number; dim: number}> = ({p, sq, sw, dim}) => {
  const yMax = NY0 + (NY1 - NY0) * p;
  if (yMax < NY0 + 20) return null;
  const L: string[] = [];
  const R: string[] = [];
  const hl: string[] = [];
  const bands: React.ReactNode[] = [];
  for (let y = NY0; y <= yMax + 0.1; y += 10) {
    const w = ancho(y, sq, sw);
    const x = nx(y);
    L.push(`${(x - w / 2).toFixed(1)} ${y}`);
    R.unshift(`${(x + w / 2).toFixed(1)} ${y}`);
    hl.push(`${(x - w * 0.18).toFixed(1)} ${y}`);
    if ((y - NY0) % 40 === 0) bands.push(<line key={y} x1={x - w / 2} y1={y} x2={x + w / 2} y2={y} stroke="#8a7632" strokeWidth={2} opacity={0.5} />);
  }
  return (
    <g opacity={1 - 0.35 * dim}>
      <polygon points={L.concat(R).join(' ')} fill="url(#nv)" stroke="#a8934a" strokeWidth={3} strokeLinejoin="round" />
      {bands}
      <polyline points={hl.join(' ')} fill="none" stroke="#fffdf2" strokeWidth={4} opacity={0.65} strokeLinecap="round" />
      {p < 0.999 && <circle cx={nx(yMax)} cy={yMax} r={26} fill={LIME} opacity={0.7} />}
    </g>
  );
};

const sqF = (s: number) => (s < 30 ? ramp(s, E[5] + 0.15, tAplast - 0.03) : 1 - ramp(s, E[8] + 0.55, tLibera - 0.1));

const Interior: React.FC = () => {
  const {s} = useS();
  const seg2 = s > 30;
  const sq = sqF(s);
  const swell = seg2 ? 0.5 * Math.max(0, golpe(s, tLibera, 10, 3.2)) : 0;
  const p = seg2 ? 1 : ramp(s, 14.95, 17.1);
  const dim = seg2 ? 1 - ramp(s, tEnc - 0.2, tEnc + 1.0) : ramp(s, 25.1, 25.9);
  const colGris = tono(s, [0, 25.1, 36.5], ['#7e95b3', '#7e95b3', '#b79a62']);
  const peso = YS - 14 - (1 - sq) * 720;
  const silla = YS + 14 + (1 - sq) * 720;
  const frente = seg2 ? NY1 - (NY1 - NY0) * ramp(s, tEnc, tEnc + 1.0) : NY1 + 10;
  const sh = sacudida(s, [tAplast, tDesord, T(122)], 11);
  const cam = [
    {t: 14.0, x: 440, y: 900, zoom: 1.1},
    {t: 17.2, x: 440, y: 1250, zoom: 1.2},
    ...seguir(NPTS, SP0, SP1, 1.35, 9),
    {t: 21.1, x: 440, y: YS, zoom: 1.6},
    {t: 25.9, x: 440, y: YS, zoom: 1.62},
    {t: 32.6, x: 440, y: YS, zoom: 1.6},
    {t: 34.7, x: 440, y: YS, zoom: 1.7},
    {t: 36.9, x: 440, y: 1000, zoom: 1.08},
    {t: 41.4, x: 440, y: 1000, zoom: 1.15},
  ];
  const nSp = Math.floor(38 * ramp(s, E[9], tDesord));
  const caos = s > E[9] - 0.1 && s < E[10] + 0.4 && sq < 0.01;
  const pp = (x: number) => 1 - Math.abs((((x % 2) + 2) % 2) - 1);
  const muerte = s - SQ1;
  const anillo = (t0: number, r: number) => {
    const d = s - t0;
    return d > 0 && d < 0.7 ? <circle cx={nx(YS)} cy={YS} r={30 + d * r} fill="none" stroke={LIME} strokeWidth={6} opacity={1 - d / 0.7} /> : null;
  };
  return (
    <AbsoluteFill style={{isolation: 'isolate'}}>
      <Textura tipo="fibra" base="radial-gradient(ellipse at 50% 50%, #1b2233, #080b14)" linea="#a73a4a30" luz="#ffffff0a" semilla={21} />
      <AbsoluteFill style={{transform: `translate(${sh.x}px,${sh.y}px)`}}>
        <Camara paradas={cam}>
          <svg viewBox="0 0 1080 1920" width="100%" height="100%" style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
            <Defs />
            <rect x={-700} y={-1500} width={2500} height={4200} fill="#0b0f1b" opacity={0.85} />
            <rect x={-700} y={-1500} width={2500} height={4200} fill="url(#rej)" />
            <rect x={535} y={-500} width={130} height={1400} rx={34} fill="url(#bo)" stroke="#6e6450" strokeWidth={5} />
            <ellipse cx={560} cy={960} rx={100} ry={74} fill="url(#bo)" stroke="#6e6450" strokeWidth={5} />
            <ellipse cx={640} cy={1076} rx={92} ry={30} fill="url(#bo)" stroke="#6e6450" strokeWidth={5} />
            <rect x={604} y={1080} width={80} height={720} rx={30} fill="url(#bo)" stroke="#6e6450" strokeWidth={5} />
            <rect x={706} y={1110} width={32} height={640} rx={14} fill="url(#bo)" stroke="#6e6450" strokeWidth={4} />
            <Musculo x={325} y0={-250} y1={560} w={175} sesgo={-14} />
            <Musculo x={320} y0={460} y1={1020} w={170} sesgo={10} />
            <Musculo x={520} y0={-260} y1={480} w={125} sesgo={8} fib={6} />
            <Musculo x={515} y0={380} y1={1010} w={120} sesgo={-8} fib={6} />
            <Musculo x={745} y0={-250} y1={600} w={125} sesgo={10} fib={6} />
            <Musculo x={740} y0={520} y1={1010} w={120} sesgo={-8} fib={6} />
            <Musculo x={330} y0={1090} y1={1690} w={160} sesgo={-22} />
            <Musculo x={520} y0={1100} y1={1640} w={120} sesgo={14} fib={6} />
            <Musculo x={780} y0={1100} y1={1580} w={90} sesgo={10} fib={4} />
            <path d="M 480 1650 C 500 1740 500 1800 520 1870 L 580 1870 C 590 1790 580 1720 560 1640 Z" fill="url(#nv)" stroke="#a8934a" strokeWidth={4} opacity={0.8} />
            {[0, 1, 2, 3].map((i) => <ellipse key={i} cx={470 + i * 70} cy={1930 + (i % 2) * 14} rx={34} ry={26} fill="url(#bo)" stroke="#6e6450" strokeWidth={4} />)}
            <path d="M 440 1760 C 380 1790 340 1840 300 1900 M 440 1500 C 500 1520 530 1560 540 1620 M 440 200 C 390 230 360 290 340 360" stroke={CREMA} strokeWidth={5} fill="none" opacity={0.6} />
            <Nervio p={p} sq={sq} sw={swell} dim={dim} />
            {seg2 && s > tEnc - 0.2 && s < tEnc + 2.2 && (
              <g>
                <polyline points={NPTS.filter(([, y]) => y >= frente).map(([x, y]) => `${x} ${y}`).join(' ')} fill="none" stroke={LIME} strokeWidth={64} opacity={0.2} strokeLinecap="round" strokeLinejoin="round" />
                <polyline points={NPTS.filter(([, y]) => y >= frente).map(([x, y]) => `${x} ${y}`).join(' ')} fill="none" stroke="#fffbd0" strokeWidth={22} opacity={0.5} strokeLinecap="round" strokeLinejoin="round" />
              </g>
            )}
            {seg2 && s > E[10] - 1.2 && s < E[10] + 0.4 && (
              <g>
                <polyline points={NPTS.map(([x, y]) => `${x} ${y}`).join(' ')} fill="none" stroke={LIME} strokeWidth={50} opacity={0.16} strokeLinecap="round" strokeLinejoin="round" />
              </g>
            )}
            {sq > 0.001 && (
              <g>
                <rect x={40} y={peso - 330} width={860} height={330} rx={110} fill="#a0704c" opacity={0.9} stroke="#5d3a24" strokeWidth={6} />
                <rect x={70} y={peso - 300} width={800} height={110} rx={50} fill="#fff" opacity={0.1} />
                <rect x={110} y={silla} width={620} height={300} rx={50} fill="#4d6a8f" stroke="#223149" strokeWidth={6} />
                <rect x={130} y={silla + 8} width={580} height={30} rx={14} fill="#fff" opacity={0.14} />
              </g>
            )}
            {s >= tAplast && s < tAplast + 0.7 && anillo(tAplast, 420)}
            {seg2 && anillo(tLibera, 520)}
            {s > SP0 - 0.3 && s < SP1 + 0.4 && (
              <Recorrido puntos={NPTS} t0={SP0} t1={SP1} render={(x, y) => <Chispa x={x} y={y} />} />
            )}
            {s > SQ0 - 0.3 && s < SQ1 && <Recorrido puntos={NPTS2} t0={SQ0} t1={SQ1} render={(x, y) => <Chispa x={x} y={y} r={1.1} />} />}
            {!seg2 && muerte > 0 && muerte < 0.7 && Array.from({length: 10}, (_, k) => {
              const a = h(k) * Math.PI * 2;
              const d = muerte * (110 + h(k + 3) * 160);
              return <circle key={k} cx={nx(YS) + Math.cos(a) * d} cy={YS + Math.sin(a) * d + muerte * 40} r={6 + h(k + 8) * 6} fill={LIME} opacity={Math.max(0, 1 - muerte / 0.6)} />;
            })}
            {caos && (
              <g>
                {Array.from({length: 38}, (_, i) => {
                  if (i >= nSp) return null;
                  const dir = i % 2 ? 1 : -1;
                  const v = 0.35 + 0.9 * h(i * 5);
                  const u = pp(h(i * 11) * 2 + dir * v * (s - E[9]));
                  const y = NY0 + (NY1 - NY0) * u;
                  const r = 0.28 + 0.3 * h(i * 3);
                  return <Chispa key={i} x={nx(y) + Math.sin(s * 20 + i) * 9} y={y} r={r} a={0.95} />;
                })}
                {Array.from({length: 22}, (_, k) => {
                  if (k >= nSp * 0.6) return null;
                  const f = ((s - E[9]) * 1.25 + h(k * 9)) % 1;
                  const by = NY0 + (NY1 - NY0) * h(k * 3 + 2);
                  const a = h(k * 5 + 1) * Math.PI * 2;
                  return <circle key={k} cx={nx(by) + Math.cos(a) * f * 380} cy={by + Math.sin(a) * f * 380} r={9 - f * 5} fill={k % 3 ? LIME : '#fff'} opacity={1 - f} />;
                })}
                {Array.from({length: 12}, (_, m) => {
                  const f = (s * 1.1 + h(m * 7)) % 1;
                  if (f > 0.12) return null;
                  const by = NY0 + (NY1 - NY0) * h(m * 3 + 7);
                  return <g key={m} transform={`translate(${nx(by)} ${by})`} opacity={1 - f / 0.12}><path d="M -26 0 H 26 M 0 -26 V 26 M -18 -18 L 18 18 M 18 -18 L -18 18" stroke="#fff" strokeWidth={5} strokeLinecap="round" /></g>;
                })}
              </g>
            )}
          </svg>
        </Camara>
      </AbsoluteFill>
      <AbsoluteFill style={{background: colGris, mixBlendMode: 'color', opacity: 0.85 * dim}} />
      <Brillo x={540} y={1000} r={640} color="rgba(255,120,110,0.07)" />
      <Profundidad color="rgba(8,6,16,0.55)" lejos="rgba(255,150,140,0.08)" manchas={3} semilla={6} deriva={0.4} />
      <Vineta a={0.62} />
    </AbsoluteFill>
  );
};

