  );
};

// ---------- sitio 5: el pie "de madera" y el cable cortado
const Cable: React.FC<{s: number}> = ({s}) => {
  const y0 = 640;
  const x0 = 90;
  const x1 = 990;
  const draw = ramp(s, tCorto - 0.65, tCorto - 0.05);
  if (draw <= 0.001) return null;
  const cortado = s >= tCorto;
  const gapPx = cortado ? ramp(s, tCorto, tCorto + 0.35) * 150 : 0;
  const jolt = golpe(s, tCorto, 22, 6) * 14;
  const N = 400;
  const pt = (i: number): [number, number] => {
    const u = i / N;
    const env = Math.min(1, u * 14, (1 - u) * 14);
    const x = x0 + (x1 - x0) * u + 11 * env * Math.cos(u * 140);
    const y = y0 + 21 * env * Math.sin(u * 140);
    return [x, y];
  };
  const mitad = N / 2;
  const gapN = (gapPx / (x1 - x0)) * N;
  const izq: string[] = [];
  const der: string[] = [];
  for (let i = 0; i <= N; i++) {
    if (i / N > draw) break;
    const [x, y] = pt(i);
    if (!cortado) izq.push(`${x.toFixed(1)},${y.toFixed(1)}`);
    else if (i <= mitad - gapN / 2) izq.push(`${(x - gapPx * 0.25 - jolt).toFixed(1)},${y.toFixed(1)}`);
    else if (i >= mitad + gapN / 2) der.push(`${(x + gapPx * 0.25 + jolt).toFixed(1)},${(y + (cortado ? (i - mitad) * 0.05 * ramp(s, tCorto, tCorto + 0.6) : 0)).toFixed(1)}`);
  }
  const trazo = (pts: string[], k: string) =>
    pts.length > 1 ? (
      <g key={k}>
        <polyline points={pts.join(' ')} fill="none" stroke="#10181f" strokeWidth={13} strokeLinecap="round" strokeLinejoin="round" />
        <polyline points={pts.join(' ')} fill="none" stroke="#243441" strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" />
        <polyline points={pts.map((p) => { const [a, b] = p.split(','); return `${Number(a) - 1},${Number(b) - 3}`; }).join(' ')} fill="none" stroke="#8ea3b6" strokeWidth={3} opacity={0.7} strokeLinecap="round" />
      </g>
    ) : null;
  const cx = (x0 + x1) / 2;
  return (
    <g>
      <g>
        <rect x={x0 - 62} y={y0 - 28} width={66} height={56} rx={10} fill="#e3dcc9" stroke="#6b6350" strokeWidth={4} />
        <rect x={x0 - 90} y={y0 - 14} width={30} height={10} fill="#b8b2a0" />
        <rect x={x0 - 90} y={y0 + 6} width={30} height={10} fill="#b8b2a0" />
      </g>
      {draw > 0.97 && (
        <g>
          <rect x={x1 - 4} y={y0 - 28} width={66} height={56} rx={10} fill="#e3dcc9" stroke="#6b6350" strokeWidth={4} transform={`translate(${cortado ? gapPx * 0.25 + jolt : 0} 0)`} />
          <rect x={x1 + 58} y={y0 - 14} width={30} height={10} fill="#b8b2a0" transform={`translate(${cortado ? gapPx * 0.25 + jolt : 0} 0)`} />
          <rect x={x1 + 58} y={y0 + 6} width={30} height={10} fill="#b8b2a0" transform={`translate(${cortado ? gapPx * 0.25 + jolt : 0} 0)`} />
        </g>
      )}
      {trazo(izq, 'i')}
      {trazo(der, 'd')}
      {cortado && (
        <g>
          {[-1, 1].map((d) => [0, 1, 2].map((k) => <path key={d + '_' + k} d={`M ${cx + d * (gapPx * 0.5 + 2)} ${y0 - 8 + k * 8} q ${d * 18} ${(k - 1) * 12} ${d * (28 + k * 8)} ${(k - 1) * 18 + Math.sin(s * 30 + k) * 3}`} stroke="#e0a050" strokeWidth={5} fill="none" strokeLinecap="round" />))}
          {s < tCorto + 0.5 && Array.from({length: 10}, (_, k) => {
            const a = h(k + 2) * Math.PI * 2;
            const d = (s - tCorto) * (120 + h(k) * 200);
            return <circle key={k} cx={cx + Math.cos(a) * d} cy={y0 + Math.sin(a) * d} r={7} fill={LIME} opacity={Math.max(0, 1 - (s - tCorto) / 0.45)} />;
          })}
          {s >= tLinea - 0.05 && s < tLinea + 0.8 && <circle cx={cx} cy={y0} r={50 + (s - tLinea) * 240} fill="none" stroke={LIME} strokeWidth={7} opacity={Math.max(0, 1 - (s - tLinea) / 0.8)} />}
        </g>
      )}
    </g>
  );
};

const Pie8: React.FC = () => {
  const {s} = useS();
  const madera = ramp(s, tMadera - 0.1, tMadera + 0.15) * (1 - ramp(s, tBien - 0.05, tBien + 0.3));
  const wipe = ramp(s, tMadera - 0.1, tMadera + 0.55);
  const tn: 'gris' | 'piel' = s < tBien - 0.05 ? 'gris' : 'piel';
  const rot = TOES.map((_, i) => Math.sin(s * 1.4 + i) * 1.5);
  const giro = Math.sin(s * 0.9) * 7;
  const esc = 1 - 0.08 * Math.abs(Math.sin(s * 0.9));
  const pulso = 1 + 0.05 * Math.max(0, golpe(s, tBien, 14, 5));
  const fondo = tono(s, [0, tBien, tBien + 0.6], ['#1f4a55', '#1f4a55', '#4a6a52']);
  const pal = [
    {t: E[7] - 0.5, x: 540, y: 1100, zoom: 1.0},
    {t: E[8], x: 540, y: 1000, zoom: 1.1},
  ];
  return (
    <AbsoluteFill>
      <Textura tipo="piel" base={`radial-gradient(ellipse at 50% 45%, ${fondo}, #0d232c 62%, #060f14 100%)`} linea="#7fb6c52a" luz="#ffe9c61c" semilla={5} />
      <Camara paradas={pal}>
        <svg viewBox="0 0 1080 1920" width="100%" height="100%" style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
          <Defs />
          <g transform={`rotate(${giro} 540 1000) translate(540 1130) scale(${esc * pulso} ${pulso}) translate(-540 -1130)`}>
            <g transform="translate(540 1130) scale(1.55)">
              <Pie uid="p8" rot={rot} tono={tn} madera={madera} wipe={wipe} sombra={false} />
            </g>
          </g>
          <Cable s={s} />
        </svg>
      </Camara>
      <Brillo x={540} y={1050} r={480} color={tn === 'piel' ? 'rgba(255,214,160,0.3)' : 'rgba(150,190,220,0.14)'} t0={0} />
      <Profundidad color="rgba(4,12,16,0.55)" lejos="rgba(190,230,240,0.1)" manchas={3} semilla={7} deriva={0.5} />
      <Vineta a={0.55} />
    </AbsoluteFill>
  );
};

// ---------- montaje: cada sitio pasa al siguiente con un Paso que cae en su palabra
const SIT: React.FC[] = [PieMacro, Sala, Interior, Cerebro, Pie8, Interior, PieMacro, Sala];
const TR: {t: number; tipo: 'alejar' | 'entrar' | 'barrido' | 'forma'; d: number; x: number; y: number}[] = [
  {t: E[1] + 0.15, tipo: 'alejar', d: 0.6, x: 540, y: 1180},
  {t: tDentro, tipo: 'entrar', d: 0.8, x: 465, y: 1078},
  {t: T(79), tipo: 'barrido', d: 0.35, x: 540, y: 1000},
  {t: E[7], tipo: 'forma', d: 0.6, x: 540, y: 1100},
  {t: E[8], tipo: 'entrar', d: 0.8, x: 540, y: 1000},
  {t: E[10], tipo: 'alejar', d: 0.8, x: 540, y: 1000},
  {t: E[12], tipo: 'forma', d: 0.6, x: 540, y: 1000},
];

export const Escena: React.FC = () => {
  const {s} = useS();
  let i = -1;
  for (let k = 0; k < TR.length; k++) if (s >= TR[k].t - TR[k].d * 0.6) i = k;
  if (i < 0) {
    const A = SIT[0];
    return <AbsoluteFill><A /></AbsoluteFill>;
  }
  const tr = TR[i];
  const Antes = SIT[i];
  const Despues = SIT[i + 1];
  return <Paso t={tr.t} tipo={tr.tipo} x={tr.x} y={tr.y} dur={tr.d} antes={<Antes />} despues={<Despues />} />;
};
